/**
 * Air Jam app config.
 *
 * Declares the runtime topology, the controller sub-route, and the Zod
 * schema controllers use to publish input to the host. `env.vite(...)`
 * resolves topology from `VITE_AIR_JAM_*` env vars; see `.env.example`.
 *
 * This minimal template doesn't actually use the input lane — taps are
 * dispatched as store actions instead — so the input schema is empty. For
 * per-frame controller input (joystick, paddle), see the pong template.
 */
import { createAirJamApp, env } from "@air-jam/sdk";
import { defineAirJamGameMetadata } from "@air-jam/sdk/metadata";
import { agentContract } from "./game/contracts/agent";
import { gameInputSchema } from "./game/input";

export const gameMetadata = defineAirJamGameMetadata({
  slug: "minimal",
  name: "Minimal",
  tagline:
    "Clean-slate starter with a shared tap counter in a tiny code surface.",
  category: "showcase",
  minPlayers: 1,
  maxPlayers: 4,
  inputModalities: ["buttons", "touch"],
  supportedSdkRange: "^1.0.0",
  maintainer: { name: "Air Jam" },
  ageRating: "all-ages",
  tags: ["starter", "minimal", "counter"],
});

export const airjam = createAirJamApp({
  runtime: env.vite(import.meta.env),
  metadata: gameMetadata,
  controllerPath: "/controller",
  agent: agentContract,
  input: {
    schema: gameInputSchema,
  },
});
import {
  agentAction,
  agentActionInput,
  agentStore,
  defineAirJamAgentContract,
  defineAirJamAgentStores,
} from "@air-jam/sdk";
import type { MinimalState } from "../store";

const stores = defineAirJamAgentStores({
  default: agentStore<MinimalState>(),
});

export const agentContract = defineAirJamAgentContract({
  stores,
  snapshotDescription:
    "Shared tap counter snapshot with semantic actions for tapping and resetting the starter state.",
  projectSnapshot: (context) => {
    const state = context.stores.default;
    if (!state) {
      return {
        available: false,
        summary: "The shared counter store is not available yet.",
      };
    }

    const leaders = Object.entries(state.perPlayerCounts)
      .sort(([, left], [, right]) => right - left)
      .slice(0, 4)
      .map(([controllerId, count]) => ({
        controllerId,
        count,
      }));

    return {
      available: true,
      totalCount: state.totalCount,
      playerCount: Object.keys(state.perPlayerCounts).length,
      perPlayerCounts: state.perPlayerCounts,
      leaders,
      availableActions: ["tap", "reset_counter"],
    };
  },
  actions: {
    tap: agentAction.participant(
      {
        actionName: "tap",
      },
      {
        input: agentActionInput.none(),
        description:
          "Increment the shared tap counter as the current controller.",
        availability: "Requires a connected controller identity.",
        resultDescription:
          "The shared counter and the current controller's personal count increment by one.",
      },
    ),
    reset_counter: agentAction.participant(
      {
        actionName: "reset",
      },
      {
        input: agentActionInput.none(),
        description:
          "Reset the minimal starter counter back to zero for deterministic retesting.",
        availability: "Any time.",
        resultDescription:
          "The shared total and all per-controller counts are cleared.",
      },
    ),
  },
});
/**
 * Networked game store. The "state lane".
 *
 * Replicated, host-authoritative state shared between the host and every
 * controller. Action handlers run on the host — when a controller calls
 * `actions.tap()`, the SDK RPCs it to the host, runs the reducer there, and
 * broadcasts the updated state back to every controller.
 *
 * The `ctx` argument injected into each action carries `actorId` (the
 * controller that initiated the action), `role` ("host" / "controller"), and
 * the current `connectedPlayerIds`. Treat it as the trustworthy identity of
 * the caller — never use fields from the payload for auth-adjacent logic.
 *
 * Important: if host code dispatches through `useStore.useActions()`, then
 * `ctx.actorId` is the host. If the host intentionally needs to run the same
 * semantic action as controller `X`, use `useStore.asPlayer("X")`.
 *
 * The reducers live here as pure functions (no SDK imports, no React) so
 * they can be unit-tested without a running session.
 */
import { createAirJamStore, type AirJamActionContext } from "@air-jam/sdk";

export interface MinimalState {
  /** Shared running total of taps across all connected controllers. */
  totalCount: number;
  /** Per-controller tap counts, keyed by `actorId` (controllerId). */
  perPlayerCounts: Record<string, number>;

  actions: {
    tap: (ctx: AirJamActionContext, payload: undefined) => void;
    reset: (ctx: AirJamActionContext, payload: undefined) => void;
  };
}

export type MinimalStateData = Omit<MinimalState, "actions">;

export const createInitialMinimalState = (): MinimalStateData => ({
  totalCount: 0,
  perPlayerCounts: {},
});

/** Increment the total + the initiating player's count. */
export const reduceTap = (
  state: MinimalStateData,
  actorId: string | undefined,
): MinimalStateData => {
  if (!actorId) return state;
  return {
    totalCount: state.totalCount + 1,
    perPlayerCounts: {
      ...state.perPlayerCounts,
      [actorId]: (state.perPlayerCounts[actorId] ?? 0) + 1,
    },
  };
};

/** Clear all counts back to zero. */
export const reduceReset = (): MinimalStateData => createInitialMinimalState();

export const useMinimalStore = createAirJamStore<MinimalState>((set) => ({
  ...createInitialMinimalState(),

  actions: {
    tap: ({ actorId }) => {
      set((state) => reduceTap(state, actorId));
    },
    reset: () => {
      set(() => reduceReset());
    },
  },
}));
/**
 * Host surface. Renders on the TV / laptop / big screen.
 *
 * Flow:
 *  1. `useAirJamHost()` gives us the live session: room id, join url, connected
 *     players.
 *  2. `useMinimalStore` pulls the replicated game state (shared count,
 *     per-player counts).
 *  3. The join URL + QR code are shown so phones can scan to join.
 *  4. When controllers tap, the store action runs here on the host, the count
 *     updates, and the new state is broadcast back to every controller.
 *  5. The "Reset" button dispatches `actions.reset()` as a host-originated
 *     action — same action pipeline, no special casing.
 *
 * No game loop, no input reading, no side effects — a counter doesn't need
 * any of that. See `pong` for a host that drives a 60fps simulation.
 */
import { useAirJamHost } from "@air-jam/sdk";
import { HostPreviewControllerWorkspace } from "@air-jam/sdk/preview";
import { RoomQrCode, SurfaceViewport } from "@air-jam/sdk/ui";
import { useEffect, useState } from "react";
import { useMinimalStore } from "../game/store";

export function HostView() {
  const host = useAirJamHost();
  const totalCount = useMinimalStore((state) => state.totalCount);
  const actions = useMinimalStore.useActions();
  const [hostNotice, setHostNotice] = useState<string | null>(null);

  // Host-only local UI effects should react here instead of going through
  // replicated state. This keeps the store authoritative but not bloated with
  // ephemeral presentation commands.
  useMinimalStore.useHostActionListener((event) => {
    if (event.actionName === "tap") {
      setHostNotice(`Tap from ${event.context.actorId}`);
      return;
    }

    if (event.actionName === "reset") {
      setHostNotice("Counter reset");
    }
  });

  useEffect(() => {
    if (!hostNotice) {
      return;
    }

    const timeoutId = window.setTimeout(() => {
      setHostNotice(null);
    }, 1200);

    return () => {
      window.clearTimeout(timeoutId);
    };
  }, [hostNotice]);

  return (
    <>
      <SurfaceViewport className="bg-neutral-950">
        <div className="flex h-full w-full flex-col items-center justify-center gap-10 p-8 text-white">
          <div className="text-xs tracking-[0.3em] text-neutral-500 uppercase">
            Shared Taps
          </div>

          <div className="text-[22vmin] leading-none font-black tabular-nums">
            {totalCount}
          </div>

          <div className="flex flex-col items-center gap-4">
            <div className="text-xs tracking-[0.2em] text-neutral-400 uppercase">
              Scan to join
            </div>
            {host.joinUrl ? (
              <RoomQrCode value={host.joinUrl} size={180} />
            ) : (
              <div className="text-sm text-neutral-500">Connecting…</div>
            )}
            <div className="text-xs text-neutral-500">
              Room: {host.roomId ?? "—"} · {host.players.length} connected
            </div>
            <div className="min-h-4 text-[0.625rem] tracking-[0.16em] text-emerald-400 uppercase">
              {hostNotice ?? "Host local effects stay local"}
            </div>
          </div>

          <button
            type="button"
            onClick={() => actions.reset()}
            className="rounded-full border border-neutral-700 bg-neutral-900 px-6 py-2 text-xs font-semibold tracking-[0.2em] text-neutral-300 uppercase hover:bg-neutral-800"
          >
            Reset
          </button>
        </div>
      </SurfaceViewport>
      <HostPreviewControllerWorkspace />
    </>
  );
}
/**
 * Controller surface. Renders on each connected phone.
 *
 * Flow:
 *  1. `useAirJamController()` gives us the session identity and connection
 *     status.
 *  2. `useMinimalStore` reads the replicated game state. `actions.tap()` is
 *     the star of the show — calling it on the controller RPCs the action to
 *     the host, which runs the reducer and broadcasts the new state back.
 * No input writer, no tick loop — taps are discrete events, not per-frame
 * intent. See `pong` for the input-lane pattern.
 */
import { useAirJamController } from "@air-jam/sdk";
import { SurfaceViewport } from "@air-jam/sdk/ui";
import { useMinimalStore } from "../game/store";

export function ControllerView() {
  const controller = useAirJamController();
  const actions = useMinimalStore.useActions();

  const myControllerId = controller.controllerId;
  const myCount = useMinimalStore((state) =>
    myControllerId ? (state.perPlayerCounts[myControllerId] ?? 0) : 0,
  );
  const totalCount = useMinimalStore((state) => state.totalCount);

  const canTap = controller.connectionStatus === "connected";

  const handleTap = () => {
    if (!canTap) return;
    actions.tap();
  };

  return (
    <SurfaceViewport orientation="portrait" className="bg-neutral-950">
      <div className="flex h-full w-full flex-col items-center justify-between gap-4 p-6 text-white">
        <div className="w-full text-center">
          <div className="text-[0.625rem] font-semibold tracking-[0.2em] text-neutral-500 uppercase">
            Room {controller.roomId ?? "—"}
          </div>
          <div className="mt-1 text-xs text-neutral-400">
            {controller.connectionStatus === "connected"
              ? "Connected — tap away"
              : `Status: ${controller.connectionStatus}`}
          </div>
        </div>

        <button
          type="button"
          onPointerDown={handleTap}
          disabled={!canTap}
          className="flex h-[50vmin] w-[50vmin] items-center justify-center rounded-full bg-emerald-500 text-4xl font-black tracking-[0.1em] text-emerald-950 uppercase shadow-lg shadow-emerald-500/30 transition active:scale-95 disabled:bg-neutral-800 disabled:text-neutral-600 disabled:shadow-none"
        >
          Tap
        </button>

        <div className="flex w-full items-baseline justify-between text-sm">
          <span className="text-neutral-400">
            Your taps:{" "}
            <span className="font-bold text-white tabular-nums">{myCount}</span>
          </span>
          <span className="text-neutral-400">
            Total:{" "}
            <span className="font-bold text-white tabular-nums">
              {totalCount}
            </span>
          </span>
        </div>
      </div>
    </SurfaceViewport>
  );
}
# Air Jam Minimal Template

The smallest possible Air Jam game. Everyone who joins gets a big TAP button
on their phone; every tap bumps a shared count shown huge on the host screen.

Use this template when you want a clean slate to build on.

## What's here

```
src/
├── airjam.config.ts   # game metadata plus SDK runtime/controller/input config
├── main.tsx           # React entry — mounts <BrowserRouter> and <App>
├── app.tsx            # Routes: "/" → host, "/controller" → controller
├── game/
│   ├── input.ts       # Controller → host input schema (empty here)
│   └── store.ts       # Networked state + actions (the tap counter)
├── host/
│   └── index.tsx      # What the TV shows
└── controller/
    └── index.tsx      # What a phone shows
```

That's the whole game. About 150 lines of actual TypeScript across the three
files in `game/`, `host/`, and `controller/`.

## Three lanes, only two used

The SDK offers three ways to move data between the host and controllers:

| Lane   | What it's for                             | Used here?                    |
| ------ | ----------------------------------------- | ----------------------------- |
| State  | Replicated store + host-authoritative RPC | Yes — `useMinimalStore`       |
| Signal | Out-of-band UX (haptics, toasts)          | No — keep this starter simple |
| Input  | High-frequency per-frame controller input | No — taps are discrete events |

When you need continuous controller input (joystick, paddle, motion),
`useInputWriter` / `useControllerTick` on the controller + `host.getInput()`
on the host is the pattern. See the `pong` template for a worked example.

## Run it

```bash
pnpm install
pnpm dev
```

Then open the printed URL on a laptop (host) and scan the QR on your phone
(controller).

## Extend it

Good places to grow from here:

1. **Add a game phase.** Replace the flat counter with a 30-second round: add
   `matchPhase: "lobby" | "playing" | "ended"` to the store, a countdown on
   the host, and a disabled state on the controller between rounds.
2. **Add real input.** Turn the button into a held accelerator: populate
   `gameInputSchema` with a `held: boolean`, publish it with
   `useInputWriter`, and read it on the host with `host.getInput(playerId)`.
3. **Add per-player identity.** `controller.selfPlayer` exposes the connected
   player profile (name, color). Show it on both surfaces. Plug
   `ControllerPlayerNameField` into the controller for editable names.
4. **Add a toast.** Use `useSendSignal()` on the host and call
   `sendSignal("TOAST", { message: "…" })` to show a banner on controllers —
   good for round results.

When any of those grow, look at `pong` as a reference for the same primitives
in a fuller shape.
