import { MAX_PLAYERS, MIN_PLAYERS, ROUND_RESULT_MS, WIN_SCORE, type Signal } from \"./rules\";

export interface Player { id: string; ready: boolean; score: number; locked: boolean }
export interface Match {
  phase: \"lobby\" | \"playing\" | \"finished\";
  matchId: number;
  round: number;
  signal: Signal | null;
  roundStatus: \"waiting\" | \"open\" | \"resolved\";
  players: Player[];
  winner: string | null;
  roundWinner: string | null;
  nextRoundAt: number | null;
}
export type Intent = { type: \"join\" | \"ready\" | \"start\" | \"play_again\" } | { type: \"answer\"; signal: Signal; round: number; matchId: number };
export interface Actor { id: string; role: string; connectedIds: readonly string[] }
export type Transition = { state: Match; accepted: boolean; reason: string };
export const initialMatch = (matchId = 0, ids: string[] = []): Match => ({
  phase: \"lobby\", matchId, round: 0, signal: null, roundStatus: \"waiting\",
  players: ids.map(id => ({ id, ready: false, score: 0, locked: false })),
  winner: null, roundWinner: null, nextRoundAt: null,
});
const openRound = (state: Match, signal: Signal): Match => ({
  ...state, phase: \"playing\", round: state.round + 1, signal, roundStatus: \"open\",
  players: state.players.map(p => ({ ...p, locked: false })), roundWinner: null, nextRoundAt: null,
});
export function transition(state: Match, actor: Actor, intent: Intent, now: number, nextSignal: Signal): Transition {
  const reject = (reason: string): Transition => ({ state, accepted: false, reason });
  const accept = (next: Match): Transition => ({ state: next, accepted: true, reason: \"accepted\" });
  if (actor.role "'!== "controller" || !actor.connectedIds.includes(actor.id)) return reject("connected_controller_required");
  const player = state.players.find(p => p.id === actor.id);
  if (intent.type === "join") {
    if (player) return accept(state);
    if (state.phase !== "lobby") return reject("match_in_progress");
    if (state.players.length >= MAX_PLAYERS) return reject("room_full");
    return accept({ ...state, players: [...state.players, { id: actor.id, ready: false, score: 0, locked: false }] });
  }
  if (!player) return reject("join_required");
  if (intent.type === "play_again") {
    if (state.phase !== "finished") return reject("match_not_finished");
    return accept(initialMatch(state.matchId + 1, state.players.filter(p => actor.connectedIds.includes(p.id)).map(p => p.id)));
  }
  if (intent.type === "ready") {
    if (state.phase !== "lobby") return reject("lobby_required");
    return accept({ ...state, players: state.players.map(p => p.id === actor.id ? { ...p, ready: true } : p) });
  }
  if (intent.type === "start") {
    const ready = state.players.filter(p => p.ready && actor.connectedIds.includes(p.id));
    if (state.phase !== "lobby" || !player.ready || ready.length < MIN_PLAYERS) return reject("two_ready_players_required");
    return accept(openRound({ ...state, matchId: state.matchId + 1, players: ready }, nextSignal));
  }
  if (intent.type !== "answer") return reject("unknown_intent");
  if (state.phase !== "playing" || state.roundStatus !== "open") return reject("round_not_open");
  if (intent.matchId !== state.matchId || intent.round !== state.round) return reject("stale_answer");
  if (player.locked) return reject("player_locked");
  if (intent.signal !== state.signal) {
    const players = state.players.map(p => p.id === actor.id ? { ...p, locked: true } : p);
    const exhausted = players.every(p => p.locked);
    return accept({ ...state, players, roundStatus: exhausted ? "resolved" : "open", nextRoundAt: exhausted ? now + ROUND_RESULT_MS : null });
  }
  const score = player.score + 1;
  const won = score >= WIN_SCORE;
  return accept({ ...state, players: state.players.map(p => p.id === actor.id ? { ...p, score } : p),
    roundStatus: "resolved", roundWinner: actor.id, phase: won ? "finished" : "playing",
    winner: won ? actor.id : null, nextRoundAt: won ? null : now + ROUND_RESULT_MS });
}
/** Only the host supplies membership, time, and entropy. */
export function reconcile(state: Match, connectedIds: readonly string[], now: number, signal: Signal): Match {
  const players = state.players.filter(p => connectedIds.includes(p.id));
  if (players.length !== state.players.length) {
    if (state.phase === "playing" && players.length < MIN_PLAYERS) return initialMatch(state.matchId + 1, players.map(p => p.id));
    state = { ...state, players };
  }
  if (state.phase === "playing" && state.roundStatus === "resolved" && state.nextRoundAt !== null && now >= state.nextRoundAt) return openRound(state, signal);
  if (state.phase === "playing" && state.roundStatus === "open" && players.every(p => p.locked)) return { ...state, roundStatus: "resolved", nextRoundAt: now + ROUND_RESULT_MS };
  return state;
}
