import { acceptAirJamAction, createAirJamStore, rejectAirJamAction, type AirJamActionContext } from \"@air-jam/sdk\";
import { initialMatch, reconcile, transition, type Intent, type Match } from \"../domain/match\";
import { SIGNALS } from \"../domain/rules\";
import { answerSchema, type Answer } from \"../contracts/inputs\";
const selectSignal = () => SIGNALS[Math.floor(Math.random() * SIGNALS.length)];
type Outcome = ReturnType<typeof acceptAirJamAction> | ReturnType<typeof rejectAirJamAction>;
export interface RelayStore extends Match {
  actions: {
    join: (ctx: AirJamActionContext, payload: undefined) => Outcome;
    ready: (ctx: AirJamActionContext, payload: undefined) => Outcome;
    start: (ctx: AirJamActionContext, payload: undefined) => Outcome;
    answer: (ctx: AirJamActionContext, payload: Answer) => Outcome;
    play_again: (ctx: AirJamActionContext, payload: undefined) => Outcome;
    tick: (ctx: AirJamActionContext, payload: undefined) => Outcome;
  };
}
export const useRelayStore = createAirJamStore<RelayStore>((set, get) => {
  const dispatch = (ctx: AirJamActionContext, intent: Intent): Outcome => {
    const result = transition(get(), { id: ctx.actorId, role: ctx.role, connectedIds: ctx.connectedPlayerIds }, intent, Date.now(), selectSignal());
    if ("'!result.accepted) return rejectAirJamAction(result.reason, result.reason.replaceAll("_", " "));
    set(result.state);
    return acceptAirJamAction();
  };
  return {
    ...initialMatch(),
    actions: {
      join: ctx => dispatch(ctx, { type: "join" }),
      ready: ctx => dispatch(ctx, { type: "ready" }),
      start: ctx => dispatch(ctx, { type: "start" }),
      play_again: ctx => dispatch(ctx, { type: "play_again" }),
      answer: (ctx, payload) => {
        const parsed = answerSchema.safeParse(payload);
        if (!parsed.success) return rejectAirJamAction("invalid_answer", "Answer must include a valid signal, matchId and round.");
        return dispatch(ctx, { type: "answer", ...parsed.data });
      },
      tick: ctx => {
        if (ctx.role !== "host") return rejectAirJamAction("host_required", "Only the host advances rounds.");
        const current = get();
        const next = reconcile(current, ctx.connectedPlayerIds, Date.now(), selectSignal());
        if (next !== current) set(next);
        return acceptAirJamAction();
      },
    },
  };
});
