    expect(act(s, \"eve\", { type: \"ready\" }).accepted).toBe(false);
    expect(transition(s, { id: \"alice\", role: \"host\", connectedIds: ids }, { type: \"ready\" }, 0, \"pulse\").accepted).toBe(false);
    expect(transition(s, { id: \"alice\", role: \"controller\", connectedIds: [] }, { type: \"ready\" }, 0, \"pulse\").accepted).toBe(false);
  });
  it(\"locks wrong answers, rejects another answer, awards just one point and clears locks next round\", () => {
    let s = started();
    s = act(s, \"alice\", answer(s, \"wave\")).state;
    expect(s.players[0].locked).toBe(true);
    expect(act(s, \"alice\", answer(s)).reason).toBe(\"player_locked\");
    s = act(s, \"bob\", answer(s)).state;
    expect(s.players[1].score).toBe(1);
    expect(act(s, \"bob\", answer(s)).accepted).toBe(false);
    s = reconcile(s, ids, ROUND_RESULT_MS, \"wave\");
    expect(s.round).toBe(2);
    expect(s.players.every(p => "'!p.locked)).toBe(true);
  });
  it("advances after everyone misses without awarding a point", () => {
    let s = started();
    for (const id of ids.slice(0, 2)) s = act(s, id, answer(s, "wave")).state;
    expect(s.roundStatus).toBe("resolved");
    s = reconcile(s, ids, ROUND_RESULT_MS, "pulse");
    expect(s.round).toBe(2);
    expect(s.players.map(p => p.score)).toEqual([0, 0]);
  });
  it("wins at exactly three points, then resets every match field and rejects stale input", () => {
    expect(WIN_SCORE).toBe(3);
    let s = started();
    const stale = answer(s);
    for (let point = 1; point <= 3; point++) {
      s = act(s, "alice", answer(s)).state;
      expect(s.players[0].score).toBe(point);
      expect(s.phase).toBe(point === 3 ? "finished" : "playing");
      if (point < 3) s = reconcile(s, ids, ROUND_RESULT_MS, "pulse");
    }
    expect(s.winner).toBe("alice");
    const priorMatch = s.matchId;
    s = act(s, "bob", { type: "play_again" }).state;
    expect(s).toEqual(initialMatch(priorMatch + 1, ["alice", "bob"]));
    for (const id of ids.slice(0, 2)) s = act(s, id, { type: "ready" }).state;
    s = act(s, "alice", { type: "start" }).state;
    expect(act(s, "alice", stale).reason).toBe("stale_answer");
  });
  it("rejects stale rounds, early reset, late joins, and malformed answers", () => {
    const s = started();
    expect(act(s, "alice", { ...answer(s), type: "answer", signal: "pulse", round: 9, matchId: s.matchId }).reason).toBe("stale_answer");
    expect(act(s, "alice", { type: "play_again" }).accepted).toBe(false);
    expect(act(s, "cy", { type: "join" }).accepted).toBe(false);
    for (const payload of [null, {}, { signal: "cheat", round: 1, matchId: 1 }, { signal: "pulse", round: 1, matchId: 1, actorId: "bob" }]) expect(answerSchema.safeParse(payload).success).toBe(false);
  });
  it("returns to a clean lobby if too few players remain", () => {
    const s = reconcile(started(), ["bob"], 0, "beam");
    expect(s.phase).toBe("lobby");
    expect(s.players).toEqual([{ id: "bob", ready: false, score: 0, locked: false }]);
  });
});
